// ==========================================
// MÓDULO 1: CARROSSEL DE IMAGENS AUTOMÁTICO
// ==========================================
function iniciarCarrossel() {
    document.querySelectorAll(".auto-slide").forEach(elementoCarrossel => {
        let imagens = elementoCarrossel.querySelectorAll(".slide-item");
        if (imagens.length <= 1) return;

        let indiceAtual = 0;
        setInterval(() => {
            indiceAtual = (indiceAtual + 1) % imagens.length;
            elementoCarrossel.style.transform = `translateX(-${100 * indiceAtual}%)`;
        }, 3500);
    });
}

// ==========================================
// MÓDULO 2: RELÓGIO DE GUERRA TÁTICO
// ==========================================
function iniciarRelogio() {
    let elementoHoras = document.getElementById("warHours");
    let elementoMinutos = document.getElementById("warMinutes");
    let elementoSegundos = document.getElementById("warSeconds");
    let elementoData = document.getElementById("warClockDate");

    if (!(elementoHoras && elementoMinutos && elementoSegundos && elementoData)) return;

    let memoriaHora = "", memoriaMinuto = "", memoriaSegundo = "";
    const meses = ["JAN", "FEV", "MAR", "ABR", "MAI", "JUN", "JUL", "AGO", "SET", "OUT", "NOV", "DEZ"];
    
    const framesAnimacao = [
        { transform: "perspective(200px) rotateX(0deg)", opacity: 1 },
        { transform: "perspective(200px) rotateX(90deg)", opacity: .5, offset: .5 },
        { transform: "perspective(200px) rotateX(0deg)", opacity: 1 }
    ];
    const opcoesAnimacao = { duration: 300, easing: "ease-in-out" };

    const atualizarTempo = () => {
        let agora = new Date();
        let h = String(agora.getHours()).padStart(2, "0");
        let m = String(agora.getMinutes()).padStart(2, "0");
        let s = String(agora.getSeconds()).padStart(2, "0");

        if (h !== memoriaHora) {
            elementoHoras.textContent = h;
            elementoHoras.animate(framesAnimacao, opcoesAnimacao);
            memoriaHora = h;
        }
        if (m !== memoriaMinuto) {
            elementoMinutos.textContent = m;
            elementoMinutos.animate(framesAnimacao, opcoesAnimacao);
            memoriaMinuto = m;
        }
        if (s !== memoriaSegundo) {
            elementoSegundos.textContent = s;
            elementoSegundos.animate(framesAnimacao, opcoesAnimacao);
            memoriaSegundo = s;
        }

        let dia = String(agora.getDate()).padStart(2, "0");
        elementoData.textContent = `${dia} ${meses[agora.getMonth()]} ${agora.getFullYear()}`;
    };

    atualizarTempo();
    setInterval(atualizarTempo, 1000);
}

// ==========================================
// MÓDULO 3: AUTENTICAÇÃO SEGURA (LOGIN / LOGOUT)
// ==========================================
function iniciarLogin(prefixoUrl) {
    let modalLogin = document.getElementById("loginModal");
    if (!modalLogin) return;

    let btnAbreModal = document.querySelector(".btn-login");
    let textoBotaoMenu = document.getElementById("navLoginText");
    let btnFechaModal = document.getElementById("closeModal");
    let formularioLogin = document.getElementById("loginForm");
    
    let inputEmail = document.getElementById("userEmail");
    let inputSenha = document.getElementById("userPassword");
    let btnAutenticar = document.getElementById("btnSubmitLogin");
    
    let btnRadar = document.getElementById("btnRadar");
    let iconeRadar = document.getElementById("radarIcon");
    let radarAtivo = false;

    const exibirBanner = (mensagem, icone = "WT - Artes/UI-UX icons/Soldier-salute.webp") => {
        let banner = document.getElementById("customBanner");
        if (banner) {
            document.getElementById("customBannerText").textContent = mensagem;
            document.getElementById("bannerIcon").innerHTML = `<img src="${prefixoUrl}${icone}" style="width:24px;height:auto;object-fit:contain;">`;
            banner.classList.add("show");
            setTimeout(() => banner.classList.remove("show"), 4000);
        }
    };

    window.atualizarControlesAdmin = function(perfilUsuario) {
        document.querySelectorAll(".admin-controls").forEach(controle => {
            controle.style.display = perfilUsuario === "admin" ? "block" : "none";
        });
    };

    const validarInputs = () => {
        let emailValido = inputEmail.value.includes("@") && inputEmail.value.includes(".");
        let senhaValida = inputSenha.value.length > 0;
        btnAutenticar.disabled = !(emailValido && senhaValida);
        btnAutenticar.classList.toggle("valido", emailValido && senhaValida);
    };

    if (btnAbreModal) {
        btnAbreModal.addEventListener("click", async (evento) => {
            evento.preventDefault();
            
            if (localStorage.getItem("isAuth") === "true") {
                try {
                    await fetch(`${prefixoUrl}php/api/logout.php`);
                    
                    localStorage.removeItem("isAuth");
                    localStorage.removeItem("userRole");
                    localStorage.removeItem("userName");
                    
                    if (textoBotaoMenu) textoBotaoMenu.textContent = "ENTRAR";
                    exibirBanner("DESCONECTADO.", "WT - Artes/UI-UX icons/Soldier-salute.webp");
                    atualizarControlesAdmin("visitante");
                    
                    setTimeout(() => window.location.reload(), 1500); 
                } catch (err) {
                    console.error("Falha ao encerrar a sessão no servidor:", err);
                    exibirBanner("Erro ao desconectar da Base Central.");
                }
            } else {
                modalLogin.classList.add("ativo");
            }
        });
    }

    if (btnFechaModal) btnFechaModal.addEventListener("click", () => modalLogin.classList.remove("ativo"));

    if (btnRadar) {
        btnRadar.addEventListener("click", () => {
            if (!radarAtivo && inputSenha.value !== "") {
                if (inputSenha.type === "password") {
                    radarAtivo = true;
                    let senhaOriginal = inputSenha.value;
                    inputSenha.type = "text";
                    iconeRadar.src = `${prefixoUrl}WT - Artes/UI-UX icons/Radar-ver.webp`;
                    inputSenha.disabled = true;
                    
                    let passos = 0;
                    let embaralhar = setInterval(() => {
                        inputSenha.value = senhaOriginal.split("").map(() => {
                            let caracteres = "ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789!@#$%&*";
                            return caracteres[Math.floor(43 * Math.random())];
                        }).join("");
                        passos++;
                        
                        if (passos > 12) {
                            clearInterval(embaralhar);
                            inputSenha.value = senhaOriginal;
                            inputSenha.disabled = false;
                            radarAtivo = false;
                        }
                    }, 40);
                } else {
                    inputSenha.type = "password";
                    iconeRadar.src = `${prefixoUrl}WT - Artes/UI-UX icons/Radar-ocultar.webp`;
                }
            }
        });
    }

    inputEmail.addEventListener("input", validarInputs);
    inputSenha.addEventListener("input", validarInputs);

    formularioLogin.addEventListener("submit", async (evento) => {
        evento.preventDefault();
        
        let emailDigitado = inputEmail.value;
        let senhaDigitada = inputSenha.value;
        
        btnAutenticar.disabled = true;
        let textoOriginalBotao = btnAutenticar.innerHTML;
        btnAutenticar.innerHTML = `<img src="${prefixoUrl}WT - Artes/UI-UX icons/Loading-icon.webp" alt="" aria-hidden="true" style="width:24px;height:auto;animation:spin 1s linear infinite;"> AUTENTICANDO...`;
        btnAutenticar.style.backgroundColor = "#F2B400";

        try {
            let formData = new FormData();
            formData.append("email", emailDigitado);
            formData.append("senha", senhaDigitada);

            const resposta = await fetch(`${prefixoUrl}php/api/auth.php`, {
                method: "POST",
                body: formData
            });
            
            const json = await resposta.json();

            setTimeout(() => {
                if (resposta.ok && json.status === "success") {
                    localStorage.setItem("isAuth", "true");
                    localStorage.setItem("userRole", json.perfil);
                    localStorage.setItem("userName", json.nome);
                    
                    document.getElementById("loginModal").classList.remove("ativo");
                    if (textoBotaoMenu) textoBotaoMenu.textContent = "SAIR";
                    
                    exibirBanner(`BEM-VINDO, ${json.nome.toUpperCase()}`);
                    atualizarControlesAdmin(json.perfil);
                    
                    btnAutenticar.innerHTML = "AUTENTICAR";
                    btnAutenticar.style.backgroundColor = "";
                    formularioLogin.reset();
                    validarInputs();
                    
                    setTimeout(() => window.location.reload(), 1500);

                } else {
                    btnAutenticar.innerHTML = "ACESSO NEGADO";
                    btnAutenticar.style.backgroundColor = "#e81000";
                    btnAutenticar.classList.remove("valido");
                    
                    exibirBanner(json.message);

                    setTimeout(() => {
                        btnAutenticar.innerHTML = "AUTENTICAR";
                        btnAutenticar.style.backgroundColor = "";
                        validarInputs();
                    }, 2500);
                }
            }, 1000);

        } catch (erro) {
            console.error("Falha de Comunicação:", erro);
            btnAutenticar.innerHTML = "FALHA NO SERVIDOR";
            btnAutenticar.style.backgroundColor = "#e81000";
            exibirBanner("Erro ao conectar à Base Central.");
            
            setTimeout(() => {
                btnAutenticar.innerHTML = "AUTENTICAR";
                btnAutenticar.style.backgroundColor = "";
                btnAutenticar.disabled = false;
            }, 2500);
        }
    });

    (function verificarSessaoInicial() {
        let isAuth = localStorage.getItem("isAuth") === "true";
        let perfilUsuario = localStorage.getItem("userRole") || "visitante";
        
        if (isAuth) {
            if (textoBotaoMenu) textoBotaoMenu.textContent = "SAIR";
            atualizarControlesAdmin(perfilUsuario);
        } else {
            if (textoBotaoMenu) textoBotaoMenu.textContent = "ENTRAR";
            atualizarControlesAdmin("visitante");
        }
    })();
}

// ==========================================
// MÓDULO 4: REGISTO DE NOVOS SOLDADOS (ALISTAMENTO)
// ==========================================
function iniciarRegistro(prefixoUrl) {
    let modalRegisto = document.getElementById("registerModal");
    let btnAbreRegisto = document.getElementById("btnOpenRegister"); 
    let btnFechaRegisto = document.getElementById("closeRegisterModal");
    let formRegisto = document.getElementById("registerForm");
    
    // Captura os campos individuais para verificarmos o preenchimento
    let inputNome = document.getElementById("regNome");
    let inputSobrenome = document.getElementById("regSobrenome");
    let inputNickname = document.getElementById("regNickname");
    let inputEmail = document.getElementById("regEmail");
    let inputSenha = document.getElementById("regSenha");
    let inputConfirmar = document.getElementById("regConfirmar");
    
    let avisoSenha = document.getElementById("regErroSenha");
    let btnSubmit = document.getElementById("btnSubmitRegister");

    if (!modalRegisto || !formRegisto) return;

    // --- NOVA LÓGICA: VALIDAÇÃO VISUAL SILENCIOSA ---
    // Esta função apenas "acende" o botão quando os campos mínimos estão preenchidos.
    // Ela NÃO exibe alertas de erro de senha, respeitando a sua regra de discrição.
    const validarBotaoVisualmente = () => {
        let camposPreenchidos = 
            inputNome.value.trim().length > 0 &&
            inputSobrenome.value.trim().length > 0 &&
            inputNickname.value.trim().length > 0 &&
            inputEmail.value.includes("@") &&
            inputSenha.value.length > 0 &&
            inputConfirmar.value.length > 0;

        if (camposPreenchidos) {
            btnSubmit.disabled = false;
            btnSubmit.classList.add("valido"); // Adiciona o CSS de botão ativo (Ex: Amarelo)
        } else {
            btnSubmit.disabled = true;
            btnSubmit.classList.remove("valido"); // Mantém o aspeto apagado/cinza
        }
    };

    // Aplica a vigilância a todos os campos obrigatórios em tempo real
    [inputNome, inputSobrenome, inputNickname, inputEmail, inputSenha, inputConfirmar].forEach(input => {
        input.addEventListener("input", validarBotaoVisualmente);
    });

    if (btnAbreRegisto) {
        btnAbreRegisto.addEventListener("click", (evento) => {
            evento.preventDefault();
            modalRegisto.classList.add("ativo");
            validarBotaoVisualmente(); // Verifica o estado assim que abre
        });
    }

    if (btnFechaRegisto) {
        btnFechaRegisto.addEventListener("click", () => {
            modalRegisto.classList.remove("ativo");
            formRegisto.reset();
            avisoSenha.style.display = "none";
            validarBotaoVisualmente(); // Reseta o estado do botão
        });
    }
    
    // --- LÓGICA DE ENVIO E VALIDAÇÃO RIGOROSA ---
    formRegisto.addEventListener("submit", async (evento) => {
        evento.preventDefault();
        
        avisoSenha.style.display = "none"; // Limpa os avisos anteriores

        // 1. Verificação de Coincidência 
        if (inputSenha.value !== inputConfirmar.value) {
            avisoSenha.textContent = "AS CHAVES CRIPTOGRÁFICAS NÃO COINCIDEM.";
            avisoSenha.style.display = "block";
            return; // Interrompe o envio
        }

        // 2. Validação de Complexidade (Min. 8 carateres, 1 Maiúscula, 1 Minúscula, 1 Número, 1 Símbolo)
        const regexSeguranca = /^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[\W_]).{8,}$/;
        if (!regexSeguranca.test(inputSenha.value)) {
            avisoSenha.textContent = "A CHAVE DEVE TER NO MÍN. 8 CARATERES (LETRAS MAIÚSCULAS E MINÚSCULAS, NÚMEROS E SÍMBOLOS).";
            avisoSenha.style.display = "block";
            return; // Interrompe o envio
        }

        // Bloqueia o botão durante o processo de comunicação
        btnSubmit.disabled = true;
        btnSubmit.classList.remove("valido");
        let textoOriginal = btnSubmit.innerHTML;
        btnSubmit.innerHTML = `<img src="${prefixoUrl}WT - Artes/UI-UX icons/Loading-icon.webp" alt="" style="width:24px;animation:spin 1s linear infinite;"> PROCESSANDO...`;

        try {
            let formData = new FormData();
            formData.append("nome", inputNome.value);
            formData.append("sobrenome", inputSobrenome.value);
            formData.append("nickname", inputNickname.value);
            formData.append("email", inputEmail.value);
            formData.append("email_contato", document.getElementById("regEmailContato").value);
            formData.append("telefone", document.getElementById("regTelefone").value);
            formData.append("senha", inputSenha.value);

            const resposta = await fetch(`${prefixoUrl}php/api/register.php`, {
                method: "POST",
                body: formData
            });
            
            // Leitura como texto para intercetar falhas do PHP que não vêm em formato JSON
            const textoResposta = await resposta.text();
            let json;
            try {
                json = JSON.parse(textoResposta);
            } catch (erroJson) {
                console.error("Resposta Inválida do Servidor (PHP):", textoResposta);
                throw new Error("O servidor retornou um erro interno e não um JSON válido.");
            }

            if (resposta.ok && json.status === "success") {
                btnSubmit.innerHTML = "ALISTAMENTO CONCLUÍDO!";
                btnSubmit.style.backgroundColor = "#4caf50"; // Verde
                
                let banner = document.getElementById("customBanner");
                if (banner) {
                    document.getElementById("customBannerText").textContent = "Soldado registado! Proceda com a autenticação.";
                    banner.classList.add("show");
                    setTimeout(() => banner.classList.remove("show"), 5000);
                }

                setTimeout(() => {
                    modalRegisto.classList.remove("ativo");
                    formRegisto.reset();
                    
                    // Restaura o botão e a interface
                    btnSubmit.innerHTML = textoOriginal;
                    btnSubmit.style.backgroundColor = "";
                    validarBotaoVisualmente(); 
                    
                    // Encaminha para o modal de Login
                    document.getElementById("loginModal").classList.add("ativo");
                }, 2000);

            } else {
                alert("ALERTA TÁTICO: " + json.message);
                btnSubmit.innerHTML = textoOriginal;
                validarBotaoVisualmente(); // Reacende o botão se houver falha de registo
            }
        } catch (erro) {
            console.error(erro);
            alert("FALHA DE COMUNICAÇÃO: " + erro.message);
            btnSubmit.innerHTML = textoOriginal;
            validarBotaoVisualmente(); // Reacende o botão para nova tentativa
        }
    });
}

// ==========================================
// MÓDULO 5: ROLAGEM SUAVE (Scroll to Top)
// ==========================================
function iniciarScrollSuave(prefixoUrl) {
    let htmlBotaoTopo = `<button id="btnVoltarTopo" title="Voltar ao Topo"><img src="${prefixoUrl}WT - Artes/UI-UX icons/Seta_cima-icon.webp" alt="" aria-hidden="true" class="icone-topo"><span class="texto-topo">VOLTAR AO TOPO</span></button>`;
    document.body.insertAdjacentHTML("beforeend", htmlBotaoTopo);
    
    let btnVoltarTopo = document.getElementById("btnVoltarTopo");
    if (btnVoltarTopo) {
        window.addEventListener("scroll", () => {
            if (window.scrollY > 300) {
                btnVoltarTopo.classList.add("visivel");
            } else {
                btnVoltarTopo.classList.remove("visivel");
            }
        });
        
        btnVoltarTopo.addEventListener("click", () => {
            document.body.scrollIntoView({ behavior: "smooth", block: "start" });
        });
        
        document.querySelectorAll('a[href^="#"]').forEach(ancora => {
            ancora.addEventListener("click", function (evento) {
                let destino = this.getAttribute("href");
                if (destino !== "#") {
                    let elementoDestino = document.querySelector(destino);
                    if (elementoDestino) {
                        evento.preventDefault();
                        elementoDestino.scrollIntoView({ behavior: "smooth", block: "start" });
                    }
                }
            });
        });
    }
}

// ==========================================
// MÓDULO 6: MOTOR DE BUSCA INTERNA
// ==========================================
function iniciarBusca(prefixoUrl) {
    let esperaInjecao = setInterval(() => {
        let inputBusca = document.getElementById("searchInput");
        let caixaSugestoes = document.getElementById("searchSuggestions");
        
        if (inputBusca && caixaSugestoes) {
            clearInterval(esperaInjecao); 
            
            let bancoVeiculos = [
                { nome: "M4A3E2 Jumbo", url: "WT - Artes/USA/USA Tanks/JUMBO/JUMBO.html", icone: "WT - Artes/USA/USA Tanks/JUMBO/JUMBO_shadow.svg" },
                { nome: "M18 Hellcat", url: "WT - Artes/USA/USA Tanks/M18/Hellcat.html", icone: "WT - Artes/USA/USA Tanks/M18/M-18 Hellcat_shadow.svg" },
                { nome: "M1A2 Abrams", url: "WT - Artes/USA/USA Tanks/M1A2-ABRAMS/M1A2-ABRAMS.html", icone: "WT - Artes/USA/USA Tanks/M1A2-ABRAMS/M1A2-Abrams_shadow.svg" },
                { nome: "T34 Heavy Tank", url: "WT - Artes/USA/USA Tanks/T34/T34.html", icone: "WT - Artes/USA/USA Tanks/T34/T34_shadow.svg" },
                { nome: "T95 Doom Turtle", url: "WT - Artes/USA/USA Tanks/T95/T95.html", icone: "WT - Artes/USA/USA Tanks/T95/T95_shadow.svg" },
                { nome: "Panther D", url: "WT - Artes/GER/Ger Tanks/PANTER D/PANTER-D.html", icone: "WT - Artes/GER/Ger Tanks/PANTER D/Panter D_shadow.svg" },
                { nome: "Tiger H1", url: "WT - Artes/GER/Ger Tanks/TIGER H1/TIGER-H1.html", icone: "WT - Artes/GER/Ger Tanks/TIGER H1/TIGER H1_shadow.svg" },
                { nome: "Tiger II V2", url: "WT - Artes/GER/Ger Tanks/TIGER II V2/TIGERII.html", icone: "WT - Artes/GER/Ger Tanks/TIGER II V2/Tiger II_shadow.svg" },
                { nome: "Sturmtiger", url: "WT - Artes/GER/Ger Tanks/STURMTIGER/Sturmtiger.html", icone: "WT - Artes/GER/Ger Tanks/STURMTIGER/Sturmtiger_shadow.svg" },
                { nome: "MAUS", url: "WT - Artes/GER/Ger Tanks/MAUS/MAUS.html", icone: "WT - Artes/GER/Ger Tanks/MAUS/MAUS_shadow.svg" },
                { nome: "T-34-85", url: "WT - Artes/RUS/Rus Tanks/T-34 85/T34-85.html", icone: "WT - Artes/RUS/Rus Tanks/T-34 85/T-34 85_shadow.svg" },
                { nome: "KV-1 (ZiS-5)", url: "WT - Artes/RUS/Rus Tanks/KV-1/KV-1.html", icone: "WT - Artes/RUS/Rus Tanks/KV-1/KV-1_shadow.svg" },
                { nome: "IS-3", url: "WT - Artes/RUS/Rus Tanks/IS-3/IS-3.html", icone: "WT - Artes/RUS/Rus Tanks/IS-3/IS-3_shadow.svg" },
                { nome: "Object 279", url: "WT - Artes/RUS/Rus Tanks/OBJ-279/OBJ-279.html", icone: "WT - Artes/RUS/Rus Tanks/OBJ-279/OBJ-279_shadow.svg" },
                { nome: "SU-100", url: "WT - Artes/RUS/Rus Tanks/SU-100/SU-100.html", icone: "WT - Artes/RUS/Rus Tanks/SU-100/SU-100_shadow.svg" },
                { nome: "Chi-Ha LG", url: "WT - Artes/JPN/JPN Tanks/CHI-RA LG/CHI-RA LG.html", icone: "WT - Artes/JPN/JPN Tanks/CHI-RA LG/CHI-RA LG_shadow.svg" },
                { nome: "Ho-Ri Production", url: "WT - Artes/JPN/JPN Tanks/HO-RI/HO-RI.html", icone: "WT - Artes/JPN/JPN Tanks/HO-RI/HO-Ri_shadow.svg" },
                { nome: "Ta-Se", url: "WT - Artes/JPN/JPN Tanks/Ta-Se/Ta-Se.html", icone: "WT - Artes/JPN/JPN Tanks/Ta-Se/Ta-Se_shadow.svg" },
                { nome: "Bkan 1C", url: "WT - Artes/SWE/SWE Tanks/BKAN 1/BKAN 1.html", icone: "WT - Artes/SWE/SWE Tanks/BKAN 1/BKAN 1_shadow.svg" },
                { nome: "BT-42", url: "WT - Artes/SWE/SWE Tanks/BT-42/BT-42.html", icone: "WT - Artes/SWE/SWE Tanks/BT-42/BT-42_shadow.svg" },
                { nome: "SAV 20.12.48", url: "WT - Artes/SWE/SWE Tanks/SAV 20.12.48/SAV-20.html", icone: "WT - Artes/SWE/SWE Tanks/SAV 20.12.48/SAV 20.12.48_shadow.svg" }
            ];
            
            let indiceSelecionado = -1;
            
            function destacarSugestao(itens) {
                itens.forEach(item => item.classList.remove("ativo"));
                if (indiceSelecionado > -1) {
                    itens[indiceSelecionado].classList.add("ativo");
                    inputBusca.value = itens[indiceSelecionado].querySelector("span").textContent;
                }
            }
            
            inputBusca.addEventListener("input", () => {
                let termoBusca = inputBusca.value.toLowerCase();
                caixaSugestoes.innerHTML = "";
                indiceSelecionado = -1;
                
                if (termoBusca.length === 0) {
                    caixaSugestoes.style.display = "none";
                    return;
                }
                
                let resultados = bancoVeiculos.filter(tanque => tanque.nome.toLowerCase().includes(termoBusca));
                
                if (resultados.length > 0) {
                    caixaSugestoes.style.display = "block";
                    resultados.forEach(tanque => {
                        let li = document.createElement("li");
                        li.innerHTML = `<a href="${prefixoUrl}${tanque.url}" class="suggestion-link"><img src="${prefixoUrl}${tanque.icone}" alt="" aria-hidden="true" class="suggestion-icon"><span>${tanque.nome}</span></a>`;
                        
                        li.addEventListener("click", () => {
                            window.location.href = `${prefixoUrl}${tanque.url}`;
                        });
                        caixaSugestoes.appendChild(li);
                    });
                } else {
                    caixaSugestoes.style.display = "none";
                }
            });
            
            inputBusca.addEventListener("keydown", evento => {
                let listaSugestoes = caixaSugestoes.querySelectorAll("li");
                if (listaSugestoes.length !== 0) {
                    if (evento.key === "ArrowDown") {
                        indiceSelecionado++;
                        if (indiceSelecionado >= listaSugestoes.length) indiceSelecionado = -1;
                        destacarSugestao(listaSugestoes);
                    } else if (evento.key === "ArrowUp") {
                        indiceSelecionado--;
                        if (indiceSelecionado < 0) indiceSelecionado = listaSugestoes.length - 1;
                        destacarSugestao(listaSugestoes);
                    } else if (evento.key === "Enter") {
                        evento.preventDefault();
                        if (indiceSelecionado > -1) {
                            listaSugestoes[indiceSelecionado].click(); 
                        }
                    }
                }
            });
            
            document.addEventListener("click", evento => {
                if (!inputBusca.contains(evento.target) && !caixaSugestoes.contains(evento.target)) {
                    caixaSugestoes.style.display = "none";
                }
            });
        }
    }, 100);
}

